package com.gojiramod.client;

import com.gojiramod.GojiraMod;
import com.gojiramod.ShowaGodzilla;
import net.minecraft.client.model.EntityModel;
import net.minecraft.client.model.geom.ModelLayerLocation;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.util.Mth;

/**
 * Showa Godzilla (0.2.0): a stocky, friendly kaiju with a round head and big eyes, a round belly, thick column legs, stubby
 * arms, a long seven-part tail and white rounded back plates. Boxes generated by tools/showa.py ({@link ShowaGodzillaModelLayer}).
 * Animations: walk, breathe, look, stomp, roar/beam jaw, swim, claw swipe, tail whip, falling over (death), and new for him:
 * jet flight, the drop kick and the victory dance.
 */
public class ShowaGodzillaModel extends EntityModel<ShowaRenderState> {
	public static final ModelLayerLocation LAYER = new ModelLayerLocation(GojiraMod.id("showa_godzilla"), "main");
	private final ModelPart rightLeg, leftLeg, rightShin, leftShin, hips, body, neck, head, jaw, rightArm, leftArm, rightForearm, leftForearm;
	private final ModelPart[] tail = new ModelPart[7];

	public ShowaGodzillaModel(final ModelPart root) {
		super(root);
		this.rightLeg = root.getChild("right_leg");
		this.leftLeg = root.getChild("left_leg");
		this.rightShin = this.rightLeg.getChild("right_shin");
		this.leftShin = this.leftLeg.getChild("left_shin");
		this.hips = root.getChild("hips");
		this.body = this.hips.getChild("body");
		this.neck = this.body.getChild("neck");
		this.head = this.neck.getChild("head");
		this.jaw = this.head.getChild("jaw");
		this.rightArm = this.body.getChild("right_arm");
		this.leftArm = this.body.getChild("left_arm");
		this.rightForearm = this.rightArm.getChild("right_forearm");
		this.leftForearm = this.leftArm.getChild("left_forearm");
		ModelPart t = this.hips;
		for (int i = 0; i < this.tail.length; i++) {
			t = t.getChild("tail" + (i + 1));
			this.tail[i] = t;
		}
	}

	public static LayerDefinition createBodyLayer() {
		return ShowaGodzillaModelLayer.create();
	}

	@Override
	public void setupAnim(final ShowaRenderState state) {
		super.setupAnim(state);
		float walk = state.walkAnimationPos, speed = Math.min(state.walkAnimationSpeed, 1.0F), t = state.ageInTicks;
		float fly = state.flyAmount, swim = state.swimAmount * (1.0F - fly), land = (1.0F - swim) * (1.0F - fly);
		// a heavy, waddling walk (Showa style: a little side-to-side rock)
		float stride = Mth.cos(walk * 0.25F) * 0.42F * speed * land;
		this.rightLeg.xRot = stride;
		this.leftLeg.xRot = -stride;
		this.rightShin.xRot += Math.max(0.0F, Mth.sin(walk * 0.25F)) * 0.3F * speed * land;
		this.leftShin.xRot += Math.max(0.0F, -Mth.sin(walk * 0.25F)) * 0.3F * speed * land;
		this.hips.zRot = Mth.sin(walk * 0.25F) * 0.07F * speed * land;
		this.body.zRot = -Mth.sin(walk * 0.25F) * 0.03F * speed * land;
		this.hips.y += Math.abs(Mth.sin(walk * 0.25F)) * -0.6F * speed * land;
		this.body.xRot += Mth.sin(t * 0.04F) * 0.02F;
		this.rightArm.xRot += Mth.sin(t * 0.05F) * 0.05F - stride * 0.3F;
		this.leftArm.xRot += Mth.sin(t * 0.05F + 1.0F) * 0.05F + stride * 0.3F;
		float sway = (Mth.sin(t * 0.03F) * 0.1F + Mth.sin(walk * 0.25F) * 0.14F * speed) * land;
		for (int i = 0; i < this.tail.length; i++) {
			this.tail[i].yRot = sway * (0.6F + 0.15F * i);
		}
		this.neck.yRot = Mth.clamp(state.yRot, -40.0F, 40.0F) * Mth.DEG_TO_RAD * 0.4F;
		this.head.yRot = Mth.clamp(state.yRot, -40.0F, 40.0F) * Mth.DEG_TO_RAD * 0.6F;
		this.head.xRot += Mth.clamp(state.xRot, -30.0F, 40.0F) * Mth.DEG_TO_RAD * 0.5F * land;

		// SWIM (like Gojira's): body flat, tail waves, legs kick, arms tucked
		if (swim > 0.0F) {
			float stroke = t * 0.16F;
			this.root().xRot += 1.15F * swim;
			this.root().y += 6.0F * swim;
			this.neck.xRot -= 0.45F * swim;
			this.head.xRot -= 0.55F * swim;
			this.hips.zRot += Mth.sin(stroke) * 0.06F * swim;
			for (int i = 0; i < this.tail.length; i++) {
				this.tail[i].yRot += Mth.sin(stroke - 0.4F * (i + 1)) * (0.22F + 0.04F * i) * swim;
			}
			this.tail[0].xRot -= 0.75F * swim;
			float kick = Mth.sin(stroke * 1.3F) * 0.55F * swim;
			this.rightLeg.xRot += 0.5F * swim + kick;
			this.leftLeg.xRot += 0.5F * swim - kick;
			this.rightShin.xRot += (0.9F + Math.max(0.0F, kick)) * swim;
			this.leftShin.xRot += (0.9F + Math.max(0.0F, -kick)) * swim;
			this.rightArm.xRot += 0.9F * swim;
			this.leftArm.xRot += 0.9F * swim;
			this.rightForearm.xRot -= 1.0F * swim;
			this.leftForearm.xRot -= 1.0F * swim;
		}

		// JET FLIGHT: the whole body tips flat, the head lifts so his open mouth points straight back (the way he faces) and
		// blasts the beam, so he flies tail first like a rocket; legs trail together, arms tucked, tail lifted in line
		if (fly > 0.0F) {
			float wobble = Mth.sin(t * 0.5F) * 0.03F;
			this.root().xRot += ShowaGodzilla.FLY_PITCH * fly + wobble;
			this.root().y += ShowaGodzilla.FLY_ROOT_DROP_PX * fly;
			this.neck.xRot -= 0.55F * fly;
			this.head.xRot -= 0.75F * fly;
			this.rightLeg.xRot += 0.35F * fly;
			this.leftLeg.xRot += 0.35F * fly;
			this.rightLeg.zRot += 0.05F * fly;
			this.leftLeg.zRot -= 0.05F * fly;
			this.rightShin.xRot += 0.5F * fly;
			this.leftShin.xRot += 0.5F * fly;
			this.rightArm.xRot += 1.0F * fly;
			this.leftArm.xRot += 1.0F * fly;
			this.rightArm.zRot -= 0.1F * fly;
			this.leftArm.zRot += 0.1F * fly;
			this.rightForearm.xRot -= 0.9F * fly;
			this.leftForearm.xRot -= 0.9F * fly;
			this.tail[0].xRot -= 1.0F * fly;
			for (int i = 1; i < this.tail.length; i++) {
				this.tail[i].xRot -= 0.05F * fly;
				this.tail[i].yRot += Mth.sin(t * 0.3F - i * 0.5F) * 0.05F * fly;
			}
		}

		// stomp: right leg up high, then SLAM
		float st = state.stompProgress;
		if (st > 0.0F) {
			float lift = st < 0.6F ? st / 0.6F : Math.max(0.0F, 1.0F - (st - 0.6F) / 0.08F);
			this.rightLeg.xRot = -1.0F * lift;
			this.rightShin.xRot += 0.8F * lift;
			this.body.xRot -= 0.15F * lift;
			this.tail[0].xRot += 0.15F * lift;
			this.rightArm.xRot -= 0.5F * lift;
			this.leftArm.xRot -= 0.5F * lift;
		}

		// claw swipe
		float sw = state.swipeProgress;
		if (sw > 0.0F) {
			float hit = (float) ShowaGodzilla.SWIPE_WINDUP / ShowaGodzilla.SWIPE_ANIM;
			float raise = sw < hit ? Mth.sin(sw / hit * Mth.HALF_PI) : 0.0F;
			float strike = sw < hit ? 0.0F : (sw < hit + 0.15F ? (sw - hit) / 0.15F : 1.0F);
			float recover = sw < hit + 0.15F ? 1.0F : Math.max(0.0F, 1.0F - (sw - hit - 0.15F) / (0.85F - hit));
			float twist = (-0.3F * raise + 0.35F * strike) * recover;
			this.body.yRot += twist;
			this.neck.yRot -= twist * 0.5F;
			this.rightArm.xRot += (-1.3F * raise + 0.6F * strike) * recover;
			this.rightArm.zRot += (0.6F * raise - 0.3F * strike) * recover;
			this.leftArm.xRot += -0.4F * (raise + strike) * recover;
			this.jaw.xRot += 0.3F * (raise + strike) * recover;
			this.tail[0].yRot -= twist * 0.6F;
		}

		// tail whip
		float wh = state.whipProgress;
		if (wh > 0.0F) {
			float hit = (float) ShowaGodzilla.WHIP_WINDUP / ShowaGodzilla.WHIP_ANIM;
			float coil = wh < hit ? Mth.sin(wh / hit * Mth.HALF_PI) : 0.0F;
			float lash = wh < hit ? 0.0F : (wh < hit + 0.15F ? (wh - hit) / 0.15F : 1.0F);
			float recover = wh < hit + 0.15F ? 1.0F : Math.max(0.0F, 1.0F - (wh - hit - 0.15F) / (0.85F - hit));
			float side = (-coil + lash) * recover;
			this.hips.yRot += side * 0.25F;
			this.body.yRot -= side * 0.15F;
			for (int i = 0; i < this.tail.length; i++) {
				this.tail[i].yRot += side * (0.25F - 0.02F * i);
			}
			this.tail[0].xRot += 0.12F * (coil + lash) * recover;
		}

		// DROP KICK (the renderer tips him back and he really jumps): crouch, then both legs shoot forward together, arms
		// fling back, chin tucked; then he lies back and gets up
		float kp = state.kickProgress;
		if (kp > 0.0F) {
			float launch = (float) ShowaGodzilla.KICK_LAUNCH / ShowaGodzilla.KICK_ANIM;
			float crouch = kp < launch ? Mth.sin(kp / launch * Mth.HALF_PI) : Math.max(0.0F, 1.0F - (kp - launch) / 0.08F);
			float k = kp < launch ? 0.0F : (kp < 0.36F ? (kp - launch) / (0.36F - launch) : (kp < 0.7F ? 1.0F : Math.max(0.0F, 1.0F - (kp - 0.7F) / 0.3F)));
			// (the renderer tips him back 75 degrees, so legs held straight under him now point forward at the target)
			this.rightLeg.xRot += -0.5F * crouch - 0.3F * k;
			this.leftLeg.xRot += -0.5F * crouch - 0.3F * k;
			this.rightShin.xRot += 0.9F * crouch - 0.2F * k;
			this.leftShin.xRot += 0.9F * crouch - 0.2F * k;
			this.rightLeg.zRot += 0.08F * k;
			this.leftLeg.zRot -= 0.08F * k;
			this.rightArm.xRot -= 0.9F * k;
			this.leftArm.xRot -= 0.9F * k;
			this.rightArm.zRot += 0.5F * k;
			this.leftArm.zRot -= 0.5F * k;
			this.neck.xRot += 0.35F * k;
			this.head.xRot += 0.3F * k;
			this.jaw.xRot += 0.3F * k;
			this.tail[0].xRot += 1.1F * k; // tail lifts so it stays out of the ground while he's tipped back
			this.tail[1].xRot += 0.15F * k;
			this.root().y += 2.0F * crouch;
		}

		// VICTORY DANCE: a happy hop from foot to foot with both arms up, hips wiggling, head bobbing and tail wagging
		float dp = state.danceProgress;
		if (dp > 0.0F) {
			float in = Math.min(1.0F, Math.min(dp, 1.0F - dp) / 0.1F);
			float beat = dp * Mth.TWO_PI * 4.0F, s = Mth.sin(beat);
			this.rightArm.xRot += -2.4F * in;
			this.leftArm.xRot += -2.4F * in;
			this.rightArm.zRot += (-0.9F + 0.3F * s) * in; // raised arms splay out in a happy V and wave
			this.leftArm.zRot += (0.9F + 0.3F * s) * in;
			this.rightForearm.xRot -= 0.3F * in;
			this.leftForearm.xRot -= 0.3F * in;
			this.hips.zRot += 0.12F * s * in;
			this.body.zRot -= 0.08F * s * in;
			this.head.zRot += 0.15F * s * in;
			this.jaw.xRot += 0.35F * in;
			this.rightLeg.xRot -= 0.5F * Math.max(0.0F, s) * in;
			this.rightShin.xRot += 0.8F * Math.max(0.0F, s) * in;
			this.leftLeg.xRot -= 0.5F * Math.max(0.0F, -s) * in;
			this.leftShin.xRot += 0.8F * Math.max(0.0F, -s) * in;
			this.root().y -= Math.abs(s) * 1.5F * in;
			for (int i = 0; i < this.tail.length; i++) {
				this.tail[i].yRot += 0.25F * s * in;
			}
		}

		// roar / beam
		float jaw = state.jawOpen;
		this.jaw.xRot += 0.7F * jaw;
		this.head.xRot -= 0.2F * jaw * land;
		this.neck.xRot -= 0.1F * state.spikeGlow * land;

		// FALLING OVER (only /kill): the renderer tips him onto his side; knees buckle, arms flop, the tail sags
		float de = state.deathProgress;
		if (de > 0.0F) {
			float buckle = Math.min(1.0F, de / 0.5F);
			this.rightShin.xRot += 0.6F * buckle;
			this.leftShin.xRot += 0.45F * buckle;
			this.rightLeg.xRot -= 0.3F * buckle;
			this.leftLeg.xRot -= 0.2F * buckle;
			this.rightArm.zRot -= 0.5F * buckle;
			this.leftArm.zRot += 0.5F * buckle;
			this.neck.xRot += 0.3F * Math.max(0.0F, (de - 0.4F) / 0.6F);
			this.tail[0].xRot -= 0.15F * buckle;
		}
	}
}
